package counter

import ("sync"; "testing")

type Counter struct{mu sync.Mutex;value int}
func(c *Counter)Inc(){c.mu.Lock();c.value++;c.mu.Unlock()}
func(c *Counter)Value()int{c.mu.Lock();defer c.mu.Unlock();return c.value}
func TestConcurrentCounter(t *testing.T){var c Counter;var wg sync.WaitGroup;for i:=0;i<20;i++{wg.Add(1);go func(){defer wg.Done();for j:=0;j<100;j++{c.Inc()}}()};wg.Wait();if got:=c.Value();got!=2000{t.Fatalf("got %d; want 2000",got)}}
// Verify with: go test -race ./...
